func TestCoreUnitCancel(t *testing.T) {
	t.Run("core.cancel", func(t *testing.T) {
		block := make(chan struct{})
		t.Cleanup(func() { close(block) })
		ts := newTestServer(t, func(w http.ResponseWriter, r *http.Request, _ int) {
			select {
			case <-block:
			case <-r.Context().Done():
			}
		})
		c := newTestTransport(t, ts.URL, nil)

		// During the request.
		ctx, cancel := context.WithCancel(t.Context())
		time.AfterFunc(30*time.Millisecond, cancel)
		_, err := ping(ctx, c)
		if CodeOf(err) != ErrorCodeCancelled || !errors.Is(err, context.Canceled) || !errors.Is(err, ErrCancelled) {
			t.Fatalf("during request: %v", err)
		}

		// During backoff.
		ts503 := newTestServer(t, status(http.StatusServiceUnavailable))
		c2 := newTestTransport(t, ts503.URL, func(cfg *CommonConfig) {
			cfg.Retry = &RetryPolicy{MaxRetries: 3, InitialBackoff: 10 * time.Second, MaxBackoff: 10 * time.Second, Rand: func() float64 { return 1 }}
		})
		ctx2, cancel2 := context.WithCancel(t.Context())
		time.AfterFunc(50*time.Millisecond, cancel2)
		start := time.Now()
		_, err = ping(ctx2, c2)
		if CodeOf(err) != ErrorCodeCancelled || !errors.Is(err, context.Canceled) || time.Since(start) > 5*time.Second {
			t.Fatalf("during backoff: %v", err)
		}
		if ts503.calls.Load() != 1 {
			t.Fatalf("attempts = %d", ts503.calls.Load())
		}

		// Before the call.
		ctx3, cancel3 := context.WithCancel(t.Context())
		cancel3()
		if _, err := ping(ctx3, c2); CodeOf(err) != ErrorCodeCancelled {
			t.Fatalf("pre-cancelled: %v", err)
		}
	})
}

func TestCoreUnitErrorsMapping(t *testing.T) {
	t.Run("core.errors.mapping", func(t *testing.T) {
		cases := map[int]ErrorCode{
			400: ErrorCodeValidation, 401: ErrorCodeAuthentication, 403: ErrorCodePermissionDenied,
			404: ErrorCodeNotFound, 409: ErrorCodeConflict, 412: ErrorCodeConflict, 413: ErrorCodeValidation,
			422: ErrorCodeValidation, 429: ErrorCodeRateLimited, 500: ErrorCodeUnavailable,
			501: ErrorCodeUnsupported, 502: ErrorCodeUnavailable, 503: ErrorCodeUnavailable, 504: ErrorCodeTimeout,
			408: ErrorCodeTimeout, 418: ErrorCodeValidation,
		}
		for code, want := range cases {
			ts := newTestServer(t, func(w http.ResponseWriter, _ *http.Request, _ int) {
				w.Header().Set("X-Request-Id", "req-42")
				w.WriteHeader(code)
			})
			c := newTestTransport(t, ts.URL, func(cfg *CommonConfig) { cfg.Retry = fastRetry(0) })
			_, err := ping(t.Context(), c)
			e := asError(t, err)
			if e.Code != want || e.HTTPStatus != code || e.RequestID != "req-42" || e.Retryable != want.Retryable() {
				t.Errorf("HTTP %d: got %+v, want %s", code, *e, want)
			}
			wantMsg := fmt.Sprintf("ping: %s (HTTP %d)", strings.ToLower(http.StatusText(code)), code)
			if e.Message != wantMsg {
				t.Errorf("HTTP %d: message %q, want %q", code, e.Message, wantMsg)
			}
		}
	})
}

func TestCoreUnitRedactionErrorText(t *testing.T) {
	t.Run("core.redaction.error-text", func(t *testing.T) {
		const token = "tok-SECRET-1234"
		ts := newTestServer(t, func(w http.ResponseWriter, _ *http.Request, _ int) {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusForbidden)
			_, _ = w.Write([]byte(`{"errors":["token tok-SECRET-1234 is not allowed"]}`))
		})
		var logs bytes.Buffer
		var mu sync.Mutex
		var hookData []string
		record := func(v any) {
			mu.Lock()
			defer mu.Unlock()
			hookData = append(hookData, fmt.Sprintf("%+v", v))
		}
		c := newTestTransport(t, ts.URL, func(cfg *CommonConfig) {
			cfg.Logger = slog.New(slog.NewJSONHandler(&logs, &slog.HandlerOptions{Level: slog.LevelDebug}))
			cfg.Hooks = &Hooks{
				OnRequest:  func(i RequestInfo) { record(i) },
				OnResponse: func(i ResponseInfo) { record(i) },
				OnError:    func(i ErrorInfo) { record(i) },
			}
			cfg.Headers = map[string]string{"X-Api-Key": "header-secret-999"}
		})
		_, err := c.do(t.Context(), &request{
			Method: http.MethodGet, Path: "/v1/secret/" + token, Header: authHeader(),
			Query: map[string][]string{"token": {token}, "page": {"2"}},
		})
		e := asError(t, err)
		if e.Code != ErrorCodePermissionDenied {
			t.Fatalf("code %s", e.Code)
		}
		if !strings.Contains(e.Message, Redacted) || !strings.Contains(e.Message, "is not allowed") {
			t.Fatalf("message %q", e.Message)
		}
		all := e.Error() + logs.String() + strings.Join(hookData, "\n")
		for _, secret := range []string{token, "header-secret-999"} {
			if strings.Contains(all, secret) {
				t.Fatalf("secret %q leaked: %s", secret, all)
			}
		}
		if len(hookData) != 3 || !strings.Contains(logs.String(), "http request") {
			t.Fatalf("hooks=%d logs=%q", len(hookData), logs.String())
		}
	})
}

