func TestCoreUnitHooks(t *testing.T) {
	t.Run("core.hooks", func(t *testing.T) {
		ts := newTestServer(t, func(w http.ResponseWriter, _ *http.Request, n int) {
			if n == 1 {
				w.WriteHeader(http.StatusBadGateway)
				return
			}
			w.Header().Set("X-Request-Id", "rid")
			w.WriteHeader(http.StatusOK)
		})
		var reqs []RequestInfo
		var resps []ResponseInfo
		var errs []ErrorInfo
		c := newTestTransport(t, ts.URL+"/base/", func(cfg *CommonConfig) {
			cfg.Hooks = &Hooks{
				OnRequest: func(i RequestInfo) {
					reqs = append(reqs, i)
					panic("hook panics are ignored")
				},
				OnResponse: func(i ResponseInfo) { resps = append(resps, i) },
				OnError: func(i ErrorInfo) {
					errs = append(errs, i)
					panic("ignored too")
				},
			}
			cfg.Logger = slog.New(panicHandler{})
		})
		if _, err := ping(t.Context(), c); err != nil {
			t.Fatalf("ping: %v", err)
		}
		if len(reqs) != 2 || reqs[0].Attempt != 1 || reqs[1].Attempt != 2 {
			t.Fatalf("requests %+v", reqs)
		}
		if reqs[0].Headers.Get("Authorization") != Redacted || reqs[0].Method != http.MethodGet {
			t.Fatalf("headers not redacted: %v", reqs[0].Headers)
		}
		if !strings.HasSuffix(reqs[0].URL, "/base/v1/ping") {
			t.Fatalf("url %q", reqs[0].URL)
		}
		if len(resps) != 2 || resps[0].Status != 502 || resps[1].Status != 200 || resps[1].RequestID != "rid" || resps[1].Attempt != 2 {
			t.Fatalf("responses %+v", resps)
		}
		if len(errs) != 1 || !errs[0].WillRetry || errs[0].Attempt != 1 || CodeOf(errs[0].Err) != ErrorCodeUnavailable {
			t.Fatalf("errors %+v", errs)
		}
	})
}

// panicHandler is a slog handler that panics; the transport must survive it.
type panicHandler struct{}

func (panicHandler) Enabled(context.Context, slog.Level) bool  { return true }
func (panicHandler) Handle(context.Context, slog.Record) error { panic("logger panic") }
func (h panicHandler) WithAttrs([]slog.Attr) slog.Handler      { return h }
func (h panicHandler) WithGroup(string) slog.Handler           { return h }

func closedAddr(t *testing.T) string {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := l.Addr().String()
	_ = l.Close()
	return addr
}

func TestTransportDetails(t *testing.T) {
	t.Run("vendor error text variants", func(t *testing.T) {
		cases := []struct {
			ct, body, want string
		}{
			{"application/json", `{"error":{"message":"inner"}}`, "inner"},
			{"application/json", `{"message":"msg"}`, "msg"},
			{"application/json", `[{"detail":"d1"},{"detail":"d2"}]`, "d1; d2"},
			{"application/json", `"plain json string"`, "plain json string"},
			{"application/json", `{"other":1}`, ""},
			{"text/plain; charset=utf-8", "first line\nsecond", "first line"},
			{"text/html", "<html>", ""},
			{"text/plain", "", ""},
		}
		for _, tc := range cases {
			res := &response{Header: http.Header{"Content-Type": {tc.ct}}, Body: []byte(tc.body)}
			if got := vendorErrorText(res); got != tc.want {
				t.Errorf("%s %q: got %q want %q", tc.ct, tc.body, got, tc.want)
			}
		}
		long := strings.Repeat("x", 400)
		e := StatusError("op", 400, "", long, nil)
		if !strings.Contains(e.Message, strings.Repeat("x", 300)+"…") || strings.Contains(e.Message, strings.Repeat("x", 301)) {
			t.Fatalf("not truncated: %d", len(e.Message))
		}
	})

	t.Run("json decode and encode errors", func(t *testing.T) {
		ts := newTestServer(t, func(w http.ResponseWriter, _ *http.Request, _ int) { _, _ = w.Write([]byte("not json")) })
		c := newTestTransport(t, ts.URL, nil)
		res, err := c.do(t.Context(), &request{Method: http.MethodGet, Path: "/version"})
		if err != nil {
			t.Fatal(err)
		}
		var out map[string]string
		if err := res.decodeJSON("version", &out); CodeOf(err) != ErrorCodeUnavailable {
			t.Fatalf("decode: %v", err)
		}
		_, err = c.do(t.Context(), &request{Method: http.MethodPost, Path: "/", JSON: make(chan int)})
		if CodeOf(err) != ErrorCodeValidation {
			t.Fatalf("encode: %v", err)
		}
		_, err = c.do(t.Context(), &request{Method: "BAD METHOD", Path: "/"})
		if CodeOf(err) != ErrorCodeValidation {
			t.Fatalf("bad method: %v", err)
		}
	})

	t.Run("raw status and request headers", func(t *testing.T) {
		ts := newTestServer(t, func(w http.ResponseWriter, r *http.Request, _ int) {
			w.Header().Set("X-Amzn-Requestid", "amz")
			w.WriteHeader(http.StatusNotFound)
		})
		c := newTestTransport(t, ts.URL, func(cfg *CommonConfig) { cfg.Headers = map[string]string{"X-Extra": "1"} })
		res, err := c.do(t.Context(), &request{
			Method: http.MethodGet, Path: "items", RawStatus: true,
			Query: map[string][]string{"q": {"a b"}}, Header: http.Header{"X-Call": {"2"}},
		})
		if err != nil || res.Status != 404 || res.RequestID != "amz" {
			t.Fatalf("res=%+v err=%v", res, err)
		}
		r := ts.request(0)
		if r.URL.RawQuery != "q=a+b" || r.Header.Get("X-Extra") != "1" || r.Header.Get("X-Call") != "2" {
			t.Fatalf("request %v %v", r.URL, r.Header)
		}
	})

	t.Run("redirects drop credentials across hosts", func(t *testing.T) {
		other := newTestServer(t, status(http.StatusOK))
		ts := newTestServer(t, func(w http.ResponseWriter, r *http.Request, _ int) {
			http.Redirect(w, r, other.URL+"/landing", http.StatusFound)
		})
		c := newTestTransport(t, ts.URL, nil)
		if _, err := ping(t.Context(), c); err != nil {
			t.Fatal(err)
		}
		if got := other.request(0).Header.Get("Authorization"); got != "" {
			t.Fatalf("credentials forwarded: %q", got)
		}
		loop := newTestServer(t, func(w http.ResponseWriter, r *http.Request, _ int) {
			http.Redirect(w, r, r.URL.Path, http.StatusFound)
		})
		c2 := newTestTransport(t, loop.URL, func(cfg *CommonConfig) { cfg.Retry = fastRetry(0) })
		if _, err := ping(t.Context(), c2); CodeOf(err) != ErrorCodeUnavailable {
			t.Fatalf("redirect loop: %v", err)
		}
	})

	t.Run("proxy is used when configured", func(t *testing.T) {
		proxy := newTestServer(t, func(w http.ResponseWriter, r *http.Request, _ int) {
			if r.URL.Host != "upstream.invalid" {
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			w.WriteHeader(http.StatusOK)
		})
		c := newTestTransport(t, "http://upstream.invalid", func(cfg *CommonConfig) { cfg.Proxy = proxy.URL })
		if _, err := ping(t.Context(), c); err != nil {
			t.Fatalf("via proxy: %v", err)
		}
	})

	t.Run("sleepContext", func(t *testing.T) {
		if err := sleepContext(t.Context(), 0); err != nil {
			t.Fatal(err)
		}
		if err := sleepContext(t.Context(), time.Millisecond); err != nil {
			t.Fatal(err)
		}
		ctx, cancel := context.WithCancel(t.Context())
		cancel()
		if err := sleepContext(ctx, time.Hour); !errors.Is(err, context.Canceled) {
			t.Fatal(err)
		}
		if remaining(context.Background(), time.Now()) <= 0 {
			t.Fatal("no deadline means unlimited")
		}
	})

	t.Run("network error without url wrapper", func(t *testing.T) {
		c := newTestTransport(t, "http://127.0.0.1:1", nil)
		plain := errors.New("boom tok-SECRET-1234")
		e := c.networkError(t.Context(), t.Context(), t.Context(), "op", plain)
		if e.Code != ErrorCodeUnavailable || strings.Contains(e.Message, "tok-SECRET") || c.redactCause(plain) != plain {
			t.Fatalf("got %+v", *e)
		}
		e = c.networkError(t.Context(), t.Context(), t.Context(), "op", timeoutErr{})
		if e.Code != ErrorCodeTimeout {
			t.Fatalf("got %+v", *e)
		}
		e = c.contextFailure(t.Context(), t.Context(), "op", context.Canceled)
		if e.Code != ErrorCodeCancelled {
			t.Fatalf("got %+v", *e)
		}
	})

	t.Run("health on a plain http server", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			w.WriteHeader(http.StatusOK)
		}))
		defer srv.Close()
		c := newTestTransport(t, srv.URL, nil)
		hs, err := c.checkHealth(t.Context(), "health", &request{Method: http.MethodGet, Path: "/health"})
		if err != nil || !hs.Healthy || hs.Status != "ok" {
			t.Fatalf("hs=%+v err=%v", hs, err)
		}
	})
}

type timeoutErr struct{}

func (timeoutErr) Error() string   { return "i/o timeout" }
func (timeoutErr) Timeout() bool   { return true }
func (timeoutErr) Temporary() bool { return true }
